// Q-062 / Q-063 (02-ui.md CMP-032, CMP-033 and § Revision — DFB-005; FRAME-043, FRAME-047, FRAME-048): the pieces of the stage-up
// moment and the spark (火花). DOM only, no state, no timers: companion.js runs the moment and look-ui.js the spark in 成长.
// Every movement is a Web Animations call, because the reduce-motion rule in companion.css kills CSS animation inside .companion.
// Art: look-art-data.js (generated by tools/make-templates.mjs from evidence/design/spark/ and stage-up/), ids turned into classes.
import { SPARK_SVG, FLARE_SVG, STAGE_UP_SVG } from './look-art-data.js';

const NS = 'http://www.w3.org/2000/svg';
export const GROWTH_SCALE = { 1: 0.72, 2: 0.86, 3: 1 }; // the same values as companion.css [data-stage] --g (CMP-031)
export const FACE_MS = 1500;        // pleasant-high face through showFace
export const CAPTION_MS = 3000;     // growth.thanks in the caption
export const SPARK_OUT_MS = 2600;   // the caption spark floats up and fades 2600-3000 ms
export const BURST_MS = 1500;       // confetti 300 ms out + 1.2 s fall
export const REDUCED_FADE_MS = 240; // the reduced moment: opacity crossfade
export const bandOf = (days) => (days >= 7 ? 3 : days >= 3 ? 2 : 1); // CMP-033 bands = the growth stages (0-2, 3-6, 7+)

// el.animate when the element has it (a test double may not); returns the Animation or null.
export const anim = (el, keyframes, options) => (el && typeof el.animate === 'function' ? el.animate(keyframes, options) : null);

function svgEl(markup, { width, height, viewBox, cls }) {
  const svg = document.createElementNS(NS, 'svg');
  svg.setAttribute('width', String(width)); svg.setAttribute('height', String(height)); svg.setAttribute('viewBox', viewBox);
  svg.setAttribute('fill', 'none'); svg.setAttribute('aria-hidden', 'true'); svg.setAttribute('focusable', 'false');
  svg.setAttribute('class', cls);
  svg.innerHTML = markup; // our own generated art, never user text
  return svg;
}

// CMP-033: one band of the spark, 24 x 24 on its 32-unit grid (flame base at 16, 29).
export const sparkSvg = (band) => svgEl(SPARK_SVG[band] ?? SPARK_SVG[1], { width: 24, height: 24, viewBox: '0 0 32 32', cls: `spark spark--${band}` });

// 成长 line: put band `band` in the holder. grow: the band stepped up -> the new band scales 0.8 -> 1 from its base with a 6 %
// overshoot and the band-3 glow fades in, 400 ms (with the bar fill). Otherwise (a lower demo band, reduced motion, first paint)
// it simply swaps. The spark never shrinks, dims or goes out.
export function setSpark(holder, band, { grow = false } = {}) {
  const spark = sparkSvg(band);
  holder.replaceChildren(spark);
  holder.dataset.band = String(band);
  if (!grow) return [];
  return [
    anim(spark, [{ transform: 'scale(0.8)' }, { transform: 'scale(1.06)', offset: 0.6 }, { transform: 'scale(1)' }], { duration: 400, easing: 'ease-out' }),
    anim(spark.querySelector('.spark-halo'), [{ opacity: 0 }, { opacity: 1 }], { duration: 400, easing: 'ease-out' }),
  ].filter(Boolean);
}

// CMP-032 / CMP-033 on the stage caption: the new band's spark in a 24 px box, 20 px after the words (CSS .caption__spark).
// Full motion: 0 -> x1.4 -> x1 from its base, ring r 12 -> 26 fading, glow, 4 twinkles once (60 ms apart), 0-600 ms; the
// 64 px flare overflows the box (centred where the Figma flare puts it: box centre = flare (32, 35)).
// Reduced: the spark only fades in with the 240 ms crossfade, still. Returns { box, anims }.
export function captionSpark(band, { reduce = false } = {}) {
  const box = document.createElement('span');
  box.className = 'caption__spark';
  box.setAttribute('aria-hidden', 'true');
  const spark = sparkSvg(band);
  box.append(spark);
  if (reduce) return { box, anims: [anim(box, [{ opacity: 0 }, { opacity: 1 }], { duration: REDUCED_FADE_MS, easing: 'linear' })].filter(Boolean) };
  const flare = svgEl(FLARE_SVG, { width: 64, height: 64, viewBox: '0 0 64 64', cls: 'spark-flare' });
  box.append(flare);
  const ring = flare.querySelector('.flare-ring');
  if (ring) { ring.style.transformBox = 'view-box'; ring.style.transformOrigin = '32px 35px'; }
  const anims = [
    anim(spark, [{ transform: 'scale(0)' }, { transform: 'scale(1.4)', offset: 0.5 }, { transform: 'scale(1)' }], { duration: 600, easing: 'ease-out' }),
    anim(ring, [{ transform: `scale(${12 / 26})`, opacity: 1 }, { transform: 'scale(1)', opacity: 0 }], { duration: 600, easing: 'ease-out', fill: 'forwards' }),
    anim(flare.querySelector('.flare-glow'), [{ opacity: 0 }, { opacity: 1, offset: 0.5 }, { opacity: 0 }], { duration: 600, fill: 'forwards' }),
  ];
  flare.querySelectorAll('[class^="flare-twinkle"]').forEach((tw, i) => {
    tw.style.transformBox = 'fill-box'; tw.style.transformOrigin = 'center';
    anims.push(anim(tw, [{ transform: 'scale(0)', opacity: 0 }, { transform: 'scale(1)', opacity: 1, offset: 0.5 }, { transform: 'scale(0)', opacity: 0 }],
      { duration: 360, delay: 120 + i * 60, easing: 'ease-out', fill: 'both' }));
  });
  return { box, anims: anims.filter(Boolean) };
}

// The caption spark leaves with the caption: floats up 12 px and fades (400 ms), never shrinks; reduced: fades 240 ms.
export const captionSparkOut = (box, { reduce = false } = {}) => anim(box, reduce
  ? [{ opacity: 1 }, { opacity: 0 }]
  : [{ transform: 'translateY(0)', opacity: 1 }, { transform: 'translateY(-12px)', opacity: 0 }],
{ duration: reduce ? REDUCED_FADE_MS : 400, easing: 'ease-in', fill: 'forwards' });

// CMP-032 confetti + sparkles: an overlay above the layers (a mood crossfade mid-moment cannot remove it), stage coordinates.
// Each confetti piece flies from (200, 170) to its drawn spot (300 ms, ease-out), then falls 60 px, turns <= 90 deg and fades
// (1.2 s). The 4 sparkles twinkle (scale 0.6 -> 1, fade) twice, 120 ms apart. Returns { overlay, anims }; the caller removes it.
export function burst() {
  const overlay = svgEl(STAGE_UP_SVG, { width: 400, height: 400, viewBox: '0 0 400 400', cls: 'companion__burst' });
  const anims = [];
  [...overlay.querySelectorAll('.confetti > *')].forEach((piece, i) => {
    const c = pieceCentre(piece);
    const wrap = document.createElementNS(NS, 'g');
    piece.replaceWith(wrap); wrap.append(piece); // the piece keeps its own rotate(); the wrapper moves
    wrap.style.transformBox = 'view-box'; wrap.style.transformOrigin = `${c.x}px ${c.y}px`;
    const turn = (i % 2 ? -1 : 1) * (40 + ((i * 13) % 50)); // 40..89 deg, alternating
    anims.push(anim(wrap, [
      { transform: `translate(${200 - c.x}px, ${170 - c.y}px)`, opacity: 0, easing: 'ease-out' },
      { transform: 'translate(0px, 0px)', opacity: 1, offset: 0.2, easing: 'ease-in' },
      { transform: `translate(0px, 60px) rotate(${turn}deg)`, opacity: 0 },
    ], { duration: BURST_MS, fill: 'both' }));
  });
  [...overlay.querySelectorAll('.sparkles-up > *')].forEach((sp, i) => {
    const m = /translate\(([-\d.]+)[ ,]+([-\d.]+)\)/.exec(sp.getAttribute('transform') ?? '') ?? [0, 200, 200];
    const wrap = document.createElementNS(NS, 'g');
    sp.replaceWith(wrap); wrap.append(sp);
    wrap.style.transformBox = 'view-box'; wrap.style.transformOrigin = `${m[1]}px ${m[2]}px`;
    anims.push(anim(wrap, [
      { transform: 'scale(0.6)', opacity: 0 }, { transform: 'scale(1)', opacity: 1, offset: 0.5 }, { transform: 'scale(0.6)', opacity: 0 },
    ], { duration: 450, iterations: 2, delay: i * 120, easing: 'ease-in-out', fill: 'both' }));
  });
  return { overlay, anims: anims.filter(Boolean) };
}

function pieceCentre(el) {
  const n = (a) => Number(el.getAttribute(a)) || 0;
  if (el.tagName.toLowerCase() === 'circle') return { x: n('cx'), y: n('cy') };
  return { x: n('x') + n('width') / 2, y: n('y') + n('height') / 2 };
}

// The new size springs in: #growth from the old scale to the new one with a 4 % overshoot, 600 ms (ground line stays put:
// companion.css gives #growth its 200 318 origin).
export const springGrowth = (svg, from, to) => anim(svg.querySelector('[id$="--growth"]'), [
  { transform: `scale(${GROWTH_SCALE[from]})` }, { transform: `scale(${GROWTH_SCALE[to] * 1.04})`, offset: 0.6 }, { transform: `scale(${GROWTH_SCALE[to]})` },
], { duration: 600, easing: 'ease-out' });

// The plant grows from the ground (scaleY 0 -> 1 at x 106, y 340), 400 ms; the old plant (a copy) fades out meanwhile.
export function growPlant(svg, oldPlant) {
  const host = svg.querySelector('[id$="--slot-plant"]');
  const fresh = host?.firstElementChild;
  if (!fresh) return [];
  fresh.style.transformBox = 'view-box'; fresh.style.transformOrigin = '106px 340px';
  const out = [anim(fresh, [{ transform: 'scaleY(0)' }, { transform: 'scaleY(1)' }], { duration: 400, easing: 'ease-out' })];
  if (oldPlant) {
    host.prepend(oldPlant);
    const fade = anim(oldPlant, [{ opacity: 1 }, { opacity: 0 }], { duration: 400, fill: 'forwards' });
    if (fade) fade.finished.then(() => oldPlant.remove(), () => oldPlant.remove()); else oldPlant.remove();
    out.push(fade);
  }
  return out.filter(Boolean);
}
